  bool blur_content = 2;
}

message TagsUserSetting {
  // Map of tag name pattern to tag metadata.
  // Each key is treated as an anchored regular expression (^pattern$),
  // so a single entry like "project/.*" matches all tags under that prefix.
  // Exact tag names are also valid.
  map<string, UserTagMetadata> tags = 1;
--
message WebhooksUserSetting {
  message Webhook {
    // Unique identifier for the webhook
    string id = 1;
    // Descriptive title for the webhook
    string title = 2;
    // The webhook URL endpoint
    string url = 3;
    // Optional signing secret for webhook authentication.
    string signing_secret = 4;
  }
  repeated Webhook webhooks = 1;
}
